import{_ as n,C as a,o as i,c as s,ao as t,E as r}from"./chunks/framework.DOMnz-Zz.js";const u=JSON.parse('{"title":"Color Coding","description":"","frontmatter":{},"headers":[],"relativePath":"guide/color-coding.md","filePath":"guide/color-coding.md","lastUpdated":null}'),d={name:"guide/color-coding.md"};function l(h,e,c,g,y,m){const o=a("DemoShot");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="Color-Coding" tabindex="-1">Color Coding <a class="header-anchor" href="#Color-Coding" aria-label="Permalink to &quot;Color Coding {#Color-Coding}&quot;">​</a></h1><p>Color coding is a cross-cutting layer. The same entity carries the same provenance no matter which mode you view it in, so Ship of Tools renders that provenance <strong>uniformly across all modes</strong> — in the design, a stale annotation looks stale in every mode, because staleness belongs to the entity, not to the view. Built today, staleness is a property of a <em>file</em> and shows on that file&#39;s row in Files mode.</p><p>Color and badging are orthogonal to mode. A mode decides <em>what tree to show</em>; the color layer decides <em>how each node is tinted</em> based on who touched it, when, and whether its annotation still matches the code.</p><div class="tip custom-block"><p class="custom-block-title">Design vs. built today</p><p>This page describes the cross-cutting colour layer as designed. What renders today is the per-session <strong>agent work-state</strong> colour (idle · working · blocked · waiting · done, on the Sessions strip and nav rows) and the <strong>stale-annotation</strong> drift badge, which is per file (the file&#39;s content hash against the annotation&#39;s <code>synced_against</code>) and shows on the selected file row in Files mode. The per-entity provenance states in the table below — user-edited, agent-edited accept/reject, immutable/external, favorited — are planned. A pinned file already renders, as a bright cyan row in the navigation tree rather than an accented border.</p></div>',4)),r(o,{name:"state-colors",caption:"Session rows in their work-state colours, each with the reason it last reported."}),e[1]||(e[1]=t('<h2 id="The-states" tabindex="-1">The states <a class="header-anchor" href="#The-states" aria-label="Permalink to &quot;The states {#The-states}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">State</th><th style="text-align:right;">Appearance</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;">User-edited recently</td><td style="text-align:right;">Warm color, fades over time</td><td style="text-align:right;">You touched this entity lately; the warmth decays as it ages.</td></tr><tr><td style="text-align:right;">Agent-edited, unaccepted</td><td style="text-align:right;">Distinct color (unresolved diff)</td><td style="text-align:right;">An agent changed this and you have not yet accepted or discarded the change.</td></tr><tr><td style="text-align:right;">Agent-edited, accepted</td><td style="text-align:right;">Neutral, small sigil</td><td style="text-align:right;">An agent&#39;s change that you accepted; marked with a small sigil but otherwise neutral.</td></tr><tr><td style="text-align:right;">Immutable / external</td><td style="text-align:right;">Dimmed</td><td style="text-align:right;">Base, dependencies, vendored code — not yours to edit, rendered dimmed.</td></tr><tr><td style="text-align:right;">Stale annotation</td><td style="text-align:right;">Yellowed</td><td style="text-align:right;">The entity&#39;s <a href="./concept-layer">concept annotation</a> was written against an older version of its file (the file&#39;s content hash differs from <code>synced_against</code>). Built per file; per-entity staleness is not built.</td></tr><tr><td style="text-align:right;">Pinned / favorited</td><td style="text-align:right;">Accented border</td><td style="text-align:right;">You marked this entity for quick return; rendered with an accented border.</td></tr></tbody></table><h2 id="Why-it-is-mode-independent" tabindex="-1">Why it is mode-independent <a class="header-anchor" href="#Why-it-is-mode-independent" aria-label="Permalink to &quot;Why it is mode-independent {#Why-it-is-mode-independent}&quot;">​</a></h2><p>Provenance is a fact about an entity: who edited it, when, whether its annotation is current. None of those facts change when you switch the root tree from Files to Modules. Encoding them once, at the entity level, means you do not relearn a color scheme per mode — a yellowed badge always means &quot;the prose may not match the code,&quot; wherever you see it.</p><p>The &quot;stale annotation&quot; state is the direct rendering of the staleness detection described in <a href="./concept-layer">The Concept Layer</a>: when an annotation&#39;s <code>synced_against</code> hash no longer matches the current content hash of its file, the file&#39;s row yellows until you refresh it. In the design the same yellow follows the entity into every mode; today it is drawn for the selected file row in Files mode only.</p>',5))])}const f=n(d,[["render",l]]);export{u as __pageData,f as default};
